impl EthereumStream {
    pub async fn new(eth: Option<EthConfig>, backlog: Backlog) -> anyhow::Result<Self> {
        let Some(eth) = eth else {
            tracing::warn!("ethereum indexer is disabled");
            return Err(anyhow::anyhow!("ethereum indexer is disabled"));
        };

